import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.C0KMm31j.js";const o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_19_four_routes.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_19_sampling_tradeoff.png",h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_19_naf_shape.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_19_amortized_actor.png",s="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_19_driving_boundary.png",f=JSON.parse('{"title":"连续动作也想用 Q-learning？四条路线终于讲清了","description":"DQN（深度 Q 网络）最关键的一步，是在当前状态比较所有动作的 Q 值并选出最大者。动作只有“左、右、刹车”时，这一步只是数组查找；转向角、加速度和制动力变成连续实数后，候选动作有无限多个，简单枚举立即失效。连续动作真正改变的不是网络能否输入动作，而是怎样高效求出 \\\\(\\\\arg\\\\maxa Q(s,","frontmatter":{"title":"连续动作也想用 Q-learning？四条路线终于讲清了","description":"DQN（深度 Q 网络）最关键的一步，是在当前状态比较所有动作的 Q 值并选出最大者。动作只有“左、右、刹车”时，这一步只是数组查找；转向角、加速度和制动力变成连续实数后，候选动作有无限多个，简单枚举立即失效。连续动作真正改变的不是网络能否输入动作，而是怎样高效求出 \\\\(\\\\arg\\\\maxa Q(s,","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":13,"source":"2026-08-13/rl_series_19_continuous_action_value_methods.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_19_four_routes.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-19-continuous-action-value-methods"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"连续动作也想用 Q-learning？四条路线终于讲清了"}],["meta",{"property":"og:description","content":"DQN（深度 Q 网络）最关键的一步，是在当前状态比较所有动作的 Q 值并选出最大者。动作只有“左、右、刹车”时，这一步只是数组查找；转向角、加速度和制动力变成连续实数后，候选动作有无限多个，简单枚举立即失效。连续动作真正改变的不是网络能否输入动作，而是怎样高效求出 \\\\(\\\\arg\\\\maxa Q(s,"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-19-continuous-action-value-methods"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_19_four_routes.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"连续动作也想用 Q-learning？四条路线终于讲清了"}],["meta",{"name":"twitter:description","content":"DQN（深度 Q 网络）最关键的一步，是在当前状态比较所有动作的 Q 值并选出最大者。动作只有“左、右、刹车”时，这一步只是数组查找；转向角、加速度和制动力变成连续实数后，候选动作有无限多个，简单枚举立即失效。连续动作真正改变的不是网络能否输入动作，而是怎样高效求出 \\\\(\\\\arg\\\\maxa Q(s,"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_19_four_routes.png"}]],"prev":{"text":"不只追求高回报，还要保留选择：SAC 的最大熵强化学习讲透了","link":"/rl/rl-series-18-sac"},"next":{"text":"奖励一直是零，智能体学什么？稀疏奖励与奖励塑形讲透了","link":"/rl/rl-series-20-sparse-reward-shaping"}},"headers":[],"relativePath":"rl/rl-series-19-continuous-action-value-methods.md","filePath":"rl/rl-series-19-continuous-action-value-methods.md","lastUpdated":null}'),d={name:"rl/rl-series-19-continuous-action-value-methods.md"};function c(p,a,u,_,b,q){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="连续动作也想用-q-learning-四条路线终于讲清了" tabindex="-1">连续动作也想用 Q-learning？四条路线终于讲清了 <a class="header-anchor" href="#连续动作也想用-q-learning-四条路线终于讲清了" aria-label="Permalink to &quot;连续动作也想用 Q-learning？四条路线终于讲清了&quot;">​</a></h1><p>DQN（深度 Q 网络）最关键的一步，是在当前状态比较所有动作的 Q 值并选出最大者。动作只有“左、右、刹车”时，这一步只是数组查找；转向角、加速度和制动力变成连续实数后，候选动作有无限多个，简单枚举立即失效。连续动作真正改变的不是网络能否输入动作，而是怎样高效求出 (\\arg\\max_a Q(s,a))。</p><p>《蘑菇书 EasyRL》第八章围绕这个难点给出四条路线：采样候选动作、对动作做梯度上升、限制 Q 函数结构，以及改用 Actor-Critic（演员—评论家）。前面三条仍在尝试“从 Q 函数里找动作”，第四条则额外训练一个 Actor（演员），把昂贵的逐状态优化摊入网络参数。本篇补齐这张方法地图，并重点解释 NAF（归一化优势函数）为什么能直接给出最优动作，又为什么没有成为连续控制的最终答案。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-难点是动作最大化而不是连续输入" tabindex="-1">1.1 难点是动作最大化而不是连续输入 <a class="header-anchor" href="#_1-1-难点是动作最大化而不是连续输入" aria-label="Permalink to &quot;1.1 难点是动作最大化而不是连续输入&quot;">​</a></h3><p>神经网络可以同时接收状态和连续动作并输出 (Q(s,a))，但训练目标和执行策略都需要求最大动作。连续空间无法逐项比较，这才是价值方法的核心障碍。</p><h3 id="_1-2-采样与梯度上升都在运行时求解动作" tabindex="-1">1.2 采样与梯度上升都在运行时求解动作 <a class="header-anchor" href="#_1-2-采样与梯度上升都在运行时求解动作" aria-label="Permalink to &quot;1.2 采样与梯度上升都在运行时求解动作&quot;">​</a></h3><p>动作采样用有限候选近似无限空间，梯度上升把动作当成优化变量。两者都不改变一般 Q 函数，但要在每次决策或目标计算时付出额外求解成本。</p><h3 id="_1-3-naf-用函数形状换来解析最优动作" tabindex="-1">1.3 NAF 用函数形状换来解析最优动作 <a class="header-anchor" href="#_1-3-naf-用函数形状换来解析最优动作" aria-label="Permalink to &quot;1.3 NAF 用函数形状换来解析最优动作&quot;">​</a></h3><p>Normalized Advantage Function（归一化优势函数，NAF）把动作优势限制为以 (\\mu(s)) 为中心的负二次型，因此 (Q(s,a)) 在动作维度的最大值必然位于 (a=\\mu(s))。最大化变简单，表达能力也随之受限。</p><h3 id="_1-4-actor-critic-把求解器变成一个可学习演员" tabindex="-1">1.4 Actor-Critic 把求解器变成一个可学习演员 <a class="header-anchor" href="#_1-4-actor-critic-把求解器变成一个可学习演员" aria-label="Permalink to &quot;1.4 Actor-Critic 把求解器变成一个可学习演员&quot;">​</a></h3><p>演员直接输出动作，评论家负责评价。DDPG（深度确定性策略梯度）、TD3（双延迟深度确定性策略梯度）和 SAC（软演员—评论家）都沿这条路线发展，但稳定性、探索和价值误差仍需分别处理。</p><p><img src="'+o+'" alt="连续动作价值方法的四条路线"></p><h2 id="二、离散-dqn-的动作选择为什么简单" tabindex="-1">二、离散 DQN 的动作选择为什么简单 <a class="header-anchor" href="#二、离散-dqn-的动作选择为什么简单" aria-label="Permalink to &quot;二、离散 DQN 的动作选择为什么简单&quot;">​</a></h2><h3 id="_2-1-网络一次输出有限个-q-值" tabindex="-1">2.1 网络一次输出有限个 Q 值 <a class="header-anchor" href="#_2-1-网络一次输出有限个-q-值" aria-label="Permalink to &quot;2.1 网络一次输出有限个 Q 值&quot;">​</a></h3><p>离散 DQN 常令网络输入状态 (s)，输出 ([Q(s,a_1),\\ldots,Q(s,a_K)])。动作数 (K) 有限，一次前向计算即可得到全部候选值。</p><h3 id="_2-2-贪心动作只是有限集合最大值" tabindex="-1">2.2 贪心动作只是有限集合最大值 <a class="header-anchor" href="#_2-2-贪心动作只是有限集合最大值" aria-label="Permalink to &quot;2.2 贪心动作只是有限集合最大值&quot;">​</a></h3><p>$$ a^*=\\arg\\max_{a\\in\\mathcal A}Q(s,a) $$</p><p>当 (\\mathcal A) 只有几个元素时，求最大值没有数值优化问题，Bellman（贝尔曼）目标中的下一动作最大值也可直接计算。</p><h3 id="_2-3-连续化后输出节点无法覆盖全部动作" tabindex="-1">2.3 连续化后输出节点无法覆盖全部动作 <a class="header-anchor" href="#_2-3-连续化后输出节点无法覆盖全部动作" aria-label="Permalink to &quot;2.3 连续化后输出节点无法覆盖全部动作&quot;">​</a></h3><p>若方向盘角度属于 ([-0.5,0.5]) 弧度，任何固定离散网格都只覆盖有限点。网格越密，动作数量和网络输出越大；网格仍会带来控制台阶，维度增加后候选数还会呈组合爆炸。</p><h2 id="三、路线一怎样用动作采样近似最大值" tabindex="-1">三、路线一怎样用动作采样近似最大值 <a class="header-anchor" href="#三、路线一怎样用动作采样近似最大值" aria-label="Permalink to &quot;三、路线一怎样用动作采样近似最大值&quot;">​</a></h2><h3 id="_3-1-从动作空间抽取有限候选" tabindex="-1">3.1 从动作空间抽取有限候选 <a class="header-anchor" href="#_3-1-从动作空间抽取有限候选" aria-label="Permalink to &quot;3.1 从动作空间抽取有限候选&quot;">​</a></h3><p>给定状态后，可以均匀、随机或围绕当前动作分布采样 (N) 个候选，将它们与同一个状态批量送入评论家，再选择 Q 值最高者。</p><p>$$ \\hat a=\\arg\\max_{a_i\\in{a_1,\\ldots,a_N}}Q(s,a_i) $$</p><h3 id="_3-2-并行计算不等于搜索免费" tabindex="-1">3.2 并行计算不等于搜索免费 <a class="header-anchor" href="#_3-2-并行计算不等于搜索免费" aria-label="Permalink to &quot;3.2 并行计算不等于搜索免费&quot;">​</a></h3><p>GPU（图形处理器）可以并行评价候选，但候选数量仍决定计算量。动作维度越高，要维持相同空间覆盖密度所需样本越多。</p><h3 id="_3-3-采样质量决定动作上限" tabindex="-1">3.3 采样质量决定动作上限 <a class="header-anchor" href="#_3-3-采样质量决定动作上限" aria-label="Permalink to &quot;3.3 采样质量决定动作上限&quot;">​</a></h3><p>真正高价值动作若没有进入候选集合，再准确的评论家也选不到它。增加随机样本能提高覆盖，却不能保证在严格实时预算内稳定找到狭窄最优区域。</p><h3 id="_3-4-采样适合作为基线和局部改进" tabindex="-1">3.4 采样适合作为基线和局部改进 <a class="header-anchor" href="#_3-4-采样适合作为基线和局部改进" aria-label="Permalink to &quot;3.4 采样适合作为基线和局部改进&quot;">​</a></h3><p>低维动作、较慢控制频率或有良好先验分布时，采样仍很实用。它也可围绕经典控制器动作做局部候选搜索，而不是覆盖整个动作空间。</p><p><img src="'+l+'" alt="有限动作采样只能近似连续空间最大值"></p><h2 id="四、路线二怎样对动作做梯度上升" tabindex="-1">四、路线二怎样对动作做梯度上升 <a class="header-anchor" href="#四、路线二怎样对动作做梯度上升" aria-label="Permalink to &quot;四、路线二怎样对动作做梯度上升&quot;">​</a></h2><h3 id="_4-1-把动作临时当成待优化参数" tabindex="-1">4.1 把动作临时当成待优化参数 <a class="header-anchor" href="#_4-1-把动作临时当成待优化参数" aria-label="Permalink to &quot;4.1 把动作临时当成待优化参数&quot;">​</a></h3><p>固定状态和评论家参数，从初始动作 (a_0) 出发重复更新：</p><p>$$ a_{k+1}=\\operatorname{clip}\\left(a_k+\\eta\\nabla_aQ(s,a_k),a_{low},a_{high}\\right) $$</p><p>其中 (\\eta) 是动作优化步长，裁剪保证动作不越过环境边界。</p><h3 id="_4-2-初始值会影响最终解" tabindex="-1">4.2 初始值会影响最终解 <a class="header-anchor" href="#_4-2-初始值会影响最终解" aria-label="Permalink to &quot;4.2 初始值会影响最终解&quot;">​</a></h3><p>神经评论家关于动作通常不是凸函数。不同初值可能走向不同局部峰值，梯度为零也不代表找到全局最大值。</p><h3 id="_4-3-每个状态都要重复迭代" tabindex="-1">4.3 每个状态都要重复迭代 <a class="header-anchor" href="#_4-3-每个状态都要重复迭代" aria-label="Permalink to &quot;4.3 每个状态都要重复迭代&quot;">​</a></h3><p>策略执行、目标计算和批量训练都可能需要求最大动作。如果每个样本都执行多步反向传播，计算和延迟会迅速增加。</p><h3 id="_4-4-评论家误差会被优化器主动利用" tabindex="-1">4.4 评论家误差会被优化器主动利用 <a class="header-anchor" href="#_4-4-评论家误差会被优化器主动利用" aria-label="Permalink to &quot;4.4 评论家误差会被优化器主动利用&quot;">​</a></h3><p>梯度上升只认评论家地形，不知道环境真实回报。若 Q 函数在数据覆盖外出现虚假尖峰，动作优化器反而会更积极地找到它。</p><h2 id="五、路线三为什么要限制-q-函数结构" tabindex="-1">五、路线三为什么要限制 Q 函数结构 <a class="header-anchor" href="#五、路线三为什么要限制-q-函数结构" aria-label="Permalink to &quot;五、路线三为什么要限制 Q 函数结构&quot;">​</a></h2><h3 id="_5-1-让最大动作可以直接写出来" tabindex="-1">5.1 让最大动作可以直接写出来 <a class="header-anchor" href="#_5-1-让最大动作可以直接写出来" aria-label="Permalink to &quot;5.1 让最大动作可以直接写出来&quot;">​</a></h3><p>与其在任意 Q 地形中搜索，不如把 Q 函数设计成在动作维度具有已知峰值。NAF 正是这种思路。</p><h3 id="_5-2-把-q-拆成状态价值与动作优势" tabindex="-1">5.2 把 Q 拆成状态价值与动作优势 <a class="header-anchor" href="#_5-2-把-q-拆成状态价值与动作优势" aria-label="Permalink to &quot;5.2 把 Q 拆成状态价值与动作优势&quot;">​</a></h3><p>$$ Q(s,a)=V(s)+A(s,a) $$</p><p>状态价值 (V(s)) 表示当前状态整体有多好，优势 (A(s,a)) 表示动作相对基准的额外价值。</p><h3 id="_5-3-优势被限制为负二次型" tabindex="-1">5.3 优势被限制为负二次型 <a class="header-anchor" href="#_5-3-优势被限制为负二次型" aria-label="Permalink to &quot;5.3 优势被限制为负二次型&quot;">​</a></h3><p>$$ A(s,a)=-\\frac{1}{2}(a-\\mu(s))^TP(s)(a-\\mu(s)) $$</p><p>其中 (P(s)) 是正定矩阵。二次项非负，前面带负号，因此优势不大于零。</p><h3 id="_5-4-最大值必然出现在中心动作" tabindex="-1">5.4 最大值必然出现在中心动作 <a class="header-anchor" href="#_5-4-最大值必然出现在中心动作" aria-label="Permalink to &quot;5.4 最大值必然出现在中心动作&quot;">​</a></h3><p>当 (a=\\mu(s)) 时，二次项为零，优势达到最大值零，于是：</p><p>$$ \\arg\\max_aQ(s,a)=\\mu(s),\\qquad \\max_aQ(s,a)=V(s) $$</p><p>这一步无需采样、迭代或额外演员优化。</p><p><img src="'+h+'" alt="NAF 通过负二次优势给出解析最优动作"></p><h2 id="六、naf-网络怎样保证矩阵正定" tabindex="-1">六、NAF 网络怎样保证矩阵正定 <a class="header-anchor" href="#六、naf-网络怎样保证矩阵正定" aria-label="Permalink to &quot;六、NAF 网络怎样保证矩阵正定&quot;">​</a></h2><h3 id="_6-1-网络同时输出三组量" tabindex="-1">6.1 网络同时输出三组量 <a class="header-anchor" href="#_6-1-网络同时输出三组量" aria-label="Permalink to &quot;6.1 网络同时输出三组量&quot;">​</a></h3><p>给定状态，网络输出 (V(s))、中心动作 (\\mu(s)) 和一个下三角矩阵 (L(s)) 所需的元素。</p><h3 id="_6-2-用矩阵乘积构造正定结构" tabindex="-1">6.2 用矩阵乘积构造正定结构 <a class="header-anchor" href="#_6-2-用矩阵乘积构造正定结构" aria-label="Permalink to &quot;6.2 用矩阵乘积构造正定结构&quot;">​</a></h3><p>常见做法是令：</p><p>$$ P(s)=L(s)L(s)^T $$</p><p>并对 (L) 的对角元素使用指数或 Softplus（平滑修正线性单元）保证为正。实际数值实现还可加入很小的对角稳定项。</p><h3 id="_6-3-评论家仍可用-q-learning-目标训练" tabindex="-1">6.3 评论家仍可用 Q-learning 目标训练 <a class="header-anchor" href="#_6-3-评论家仍可用-q-learning-目标训练" aria-label="Permalink to &quot;6.3 评论家仍可用 Q-learning 目标训练&quot;">​</a></h3><p>由于下一状态最大 Q 值等于目标网络输出的 (V_{targ}(s&#39;))，目标可写为：</p><p>$$ y=r+\\gamma(1-d)V_{targ}(s&#39;) $$</p><p>主网络再最小化 ((Q(s,a)-y)^2)，并配合 Replay Buffer（回放缓冲区）和 Target Network（目标网络）。</p><h3 id="_6-4-行为探索仍需额外噪声" tabindex="-1">6.4 行为探索仍需额外噪声 <a class="header-anchor" href="#_6-4-行为探索仍需额外噪声" aria-label="Permalink to &quot;6.4 行为探索仍需额外噪声&quot;">​</a></h3><p>中心动作 (\\mu(s)) 是确定性的。训练交互通常仍要叠加噪声，并将环境真正执行的动作存入回放池。</p><h2 id="七、naf-用什么代价换来解析最大值" tabindex="-1">七、NAF 用什么代价换来解析最大值 <a class="header-anchor" href="#七、naf-用什么代价换来解析最大值" aria-label="Permalink to &quot;七、NAF 用什么代价换来解析最大值&quot;">​</a></h2><h3 id="_7-1-每个状态只有一个二次型峰值" tabindex="-1">7.1 每个状态只有一个二次型峰值 <a class="header-anchor" href="#_7-1-每个状态只有一个二次型峰值" aria-label="Permalink to &quot;7.1 每个状态只有一个二次型峰值&quot;">​</a></h3><p>NAF 假设 Q 函数关于动作近似单峰二次曲面。如果同一状态下存在多个相距较远的高价值动作，这种结构难以完整表达。</p><h3 id="_7-2-高维矩阵增加网络输出和数值负担" tabindex="-1">7.2 高维矩阵增加网络输出和数值负担 <a class="header-anchor" href="#_7-2-高维矩阵增加网络输出和数值负担" aria-label="Permalink to &quot;7.2 高维矩阵增加网络输出和数值负担&quot;">​</a></h3><p>动作维度为 (m) 时，下三角矩阵需要 (m(m+1)/2) 个元素。维度升高后，输出量和矩阵运算都会增长。</p><h3 id="_7-3-可解析贪心不代表价值估计准确" tabindex="-1">7.3 可解析贪心不代表价值估计准确 <a class="header-anchor" href="#_7-3-可解析贪心不代表价值估计准确" aria-label="Permalink to &quot;7.3 可解析贪心不代表价值估计准确&quot;">​</a></h3><p>NAF 解决的是“怎样从所学 Q 中取最大值”，没有消除自举、函数逼近和异策略数据共同导致的误差。</p><h3 id="_7-4-结构假设可能带来系统性偏差" tabindex="-1">7.4 结构假设可能带来系统性偏差 <a class="header-anchor" href="#_7-4-结构假设可能带来系统性偏差" aria-label="Permalink to &quot;7.4 结构假设可能带来系统性偏差&quot;">​</a></h3><p>评论家即使训练损失很低，也可能因为形状受限而错过真实动作价值结构。低损失只能说明拟合目标，不证明环境性能最优。</p><h2 id="八、路线四为什么训练一个演员更通用" tabindex="-1">八、路线四为什么训练一个演员更通用 <a class="header-anchor" href="#八、路线四为什么训练一个演员更通用" aria-label="Permalink to &quot;八、路线四为什么训练一个演员更通用&quot;">​</a></h2><h3 id="_8-1-演员摊销逐状态动作优化" tabindex="-1">8.1 演员摊销逐状态动作优化 <a class="header-anchor" href="#_8-1-演员摊销逐状态动作优化" aria-label="Permalink to &quot;8.1 演员摊销逐状态动作优化&quot;">​</a></h3><p>Actor-Critic 令 (a=\\mu_\\theta(s)) 或从 (\\pi_\\theta(a|s)) 采样。训练阶段用评论家指导演员，执行阶段只需一次前向计算。</p><h3 id="_8-2-评论家不必保持固定二次形状" tabindex="-1">8.2 评论家不必保持固定二次形状 <a class="header-anchor" href="#_8-2-评论家不必保持固定二次形状" aria-label="Permalink to &quot;8.2 评论家不必保持固定二次形状&quot;">​</a></h3><p>评论家可以学习更一般的 (Q(s,a))，演员负责在数据支持范围内逼近较优动作。表达能力更强，优化耦合也更复杂。</p><h3 id="_8-3-确定性和随机演员对应不同探索机制" tabindex="-1">8.3 确定性和随机演员对应不同探索机制 <a class="header-anchor" href="#_8-3-确定性和随机演员对应不同探索机制" aria-label="Permalink to &quot;8.3 确定性和随机演员对应不同探索机制&quot;">​</a></h3><p>DDPG 与 TD3 的演员是确定性的，训练行为需要额外噪声；SAC 直接学习随机策略，并把熵写入目标。两者不是简单的“有无噪声”差异。</p><h3 id="_8-4-演员仍可能利用评论家误差" tabindex="-1">8.4 演员仍可能利用评论家误差 <a class="header-anchor" href="#_8-4-演员仍可能利用评论家误差" aria-label="Permalink to &quot;8.4 演员仍可能利用评论家误差&quot;">​</a></h3><p>演员沿评论家梯度更新，与动作梯度上升面对同一根本风险：错误价值地形会产生错误动作方向。双评论家、目标平滑和保守学习只能缓解特定误差。</p><p><img src="'+n+'" alt="从在线动作优化到可学习演员的计算迁移"></p><h2 id="九、四条路线应该怎样比较" tabindex="-1">九、四条路线应该怎样比较 <a class="header-anchor" href="#九、四条路线应该怎样比较" aria-label="Permalink to &quot;九、四条路线应该怎样比较&quot;">​</a></h2><h3 id="_9-1-比较执行延迟" tabindex="-1">9.1 比较执行延迟 <a class="header-anchor" href="#_9-1-比较执行延迟" aria-label="Permalink to &quot;9.1 比较执行延迟&quot;">​</a></h3><p>采样需要多次 Q 前向，梯度上升需要多轮前向与反向，NAF 和演员通常一次前向即可给出动作。实时控制首先要报告端到端延迟，而非只报告回报。</p><h3 id="_9-2-比较动作空间维度" tabindex="-1">9.2 比较动作空间维度 <a class="header-anchor" href="#_9-2-比较动作空间维度" aria-label="Permalink to &quot;9.2 比较动作空间维度&quot;">​</a></h3><p>候选采样在高维空间覆盖困难，NAF 的矩阵参数随维度二次增长，演员方法的输出通常随维度线性增长，但评论家训练可能更难。</p><h3 id="_9-3-比较价值函数表达能力" tabindex="-1">9.3 比较价值函数表达能力 <a class="header-anchor" href="#_9-3-比较价值函数表达能力" aria-label="Permalink to &quot;9.3 比较价值函数表达能力&quot;">​</a></h3><p>一般 Q 函数最灵活，NAF 主动施加单峰二次结构。表达能力与可优化性之间不存在免费的提升。</p><h3 id="_9-4-比较数据覆盖和外推风险" tabindex="-1">9.4 比较数据覆盖和外推风险 <a class="header-anchor" href="#_9-4-比较数据覆盖和外推风险" aria-label="Permalink to &quot;9.4 比较数据覆盖和外推风险&quot;">​</a></h3><p>所有依赖评论家的方案都要检查所选动作是否落在回放数据支持范围内。最大 Q 值高但真实回报低，是比训练损失更直接的警报。</p><h2 id="十、自动驾驶中应怎样理解这些方法" tabindex="-1">十、自动驾驶中应怎样理解这些方法 <a class="header-anchor" href="#十、自动驾驶中应怎样理解这些方法" aria-label="Permalink to &quot;十、自动驾驶中应怎样理解这些方法&quot;">​</a></h2><h3 id="_10-1-连续控制变量并不只有方向盘" tabindex="-1">10.1 连续控制变量并不只有方向盘 <a class="header-anchor" href="#_10-1-连续控制变量并不只有方向盘" aria-label="Permalink to &quot;10.1 连续控制变量并不只有方向盘&quot;">​</a></h3><p>横向转角、纵向加速度、期望曲率、目标速度和轨迹参数都可能是连续动作。不同动作定义对应不同动力学约束与执行延迟。</p><h3 id="_10-2-动作解析可解不等于车辆约束可解" tabindex="-1">10.2 动作解析可解不等于车辆约束可解 <a class="header-anchor" href="#_10-2-动作解析可解不等于车辆约束可解" aria-label="Permalink to &quot;10.2 动作解析可解不等于车辆约束可解&quot;">​</a></h3><p>NAF 的 (\\mu(s)) 最大化学习到的 Q 值，并不自动满足轮胎附着、转角速率、碰撞距离或舒适性约束。</p><h3 id="_10-3-局部价值峰值不等于系统安全" tabindex="-1">10.3 局部价值峰值不等于系统安全 <a class="header-anchor" href="#_10-3-局部价值峰值不等于系统安全" aria-label="Permalink to &quot;10.3 局部价值峰值不等于系统安全&quot;">​</a></h3><p>评论家是数据驱动预测器，不是可验证控制 Lyapunov Function（李雅普诺夫函数）或 Control Barrier Function（控制屏障函数）。安全过滤、备用控制和故障降级仍需独立设计。</p><h3 id="_10-4-经典控制器是必要对照" tabindex="-1">10.4 经典控制器是必要对照 <a class="header-anchor" href="#_10-4-经典控制器是必要对照" aria-label="Permalink to &quot;10.4 经典控制器是必要对照&quot;">​</a></h3><p>在低维规控任务中，PID（比例—积分—微分控制）、Stanley（斯坦利控制器）或 MPC（模型预测控制）往往具有更清楚的延迟、约束和稳定性边界。连续强化学习必须在相同场景和资源预算下与它们比较。</p><p><img src="'+s+'" alt="连续强化学习输出与车辆安全执行链的边界"></p><h2 id="十一、一个最小实验怎样设计" tabindex="-1">十一、一个最小实验怎样设计 <a class="header-anchor" href="#十一、一个最小实验怎样设计" aria-label="Permalink to &quot;十一、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_11-1-选择一维或二维连续动作" tabindex="-1">11.1 选择一维或二维连续动作 <a class="header-anchor" href="#_11-1-选择一维或二维连续动作" aria-label="Permalink to &quot;11.1 选择一维或二维连续动作&quot;">​</a></h3><p>从摆杆、连续速度控制或简化车道保持开始，先保证动作缩放、终止语义和评价脚本正确。</p><h3 id="_11-2-建立离散化与经典控制基线" tabindex="-1">11.2 建立离散化与经典控制基线 <a class="header-anchor" href="#_11-2-建立离散化与经典控制基线" aria-label="Permalink to &quot;11.2 建立离散化与经典控制基线&quot;">​</a></h3><p>离散动作 DQN 可展示分辨率代价，经典控制器提供非学习参照。不要只比较多个深度算法。</p><h3 id="_11-3-实现候选采样、naf-与演员方法" tabindex="-1">11.3 实现候选采样、NAF 与演员方法 <a class="header-anchor" href="#_11-3-实现候选采样、naf-与演员方法" aria-label="Permalink to &quot;11.3 实现候选采样、NAF 与演员方法&quot;">​</a></h3><p>统一网络规模、环境步数、回放容量和评估次数，分别记录学习曲线、动作误差与执行延迟。</p><h3 id="_11-4-检查评论家局部动作曲线" tabindex="-1">11.4 检查评论家局部动作曲线 <a class="header-anchor" href="#_11-4-检查评论家局部动作曲线" aria-label="Permalink to &quot;11.4 检查评论家局部动作曲线&quot;">​</a></h3><p>固定若干状态，在动作范围内扫描真实 Q 预测，观察是否单峰、是否在数据边缘产生虚假高值，以及 NAF 二次假设是否合理。</p><h3 id="_11-5-使用多个随机种子报告分布" tabindex="-1">11.5 使用多个随机种子报告分布 <a class="header-anchor" href="#_11-5-使用多个随机种子报告分布" aria-label="Permalink to &quot;11.5 使用多个随机种子报告分布&quot;">​</a></h3><p>报告中位数、分位区间和失败运行，而不是挑选最好曲线。连续控制对初始化和探索噪声十分敏感。</p><h2 id="十二、最常见的理解错误" tabindex="-1">十二、最常见的理解错误 <a class="header-anchor" href="#十二、最常见的理解错误" aria-label="Permalink to &quot;十二、最常见的理解错误&quot;">​</a></h2><h3 id="_12-1-把连续动作输入误当成连续动作求解" tabindex="-1">12.1 把连续动作输入误当成连续动作求解 <a class="header-anchor" href="#_12-1-把连续动作输入误当成连续动作求解" aria-label="Permalink to &quot;12.1 把连续动作输入误当成连续动作求解&quot;">​</a></h3><p>网络能接收 (a) 只解决估值接口，没有解决 (\\arg\\max_a Q(s,a))。</p><h3 id="_12-2-把-naf-的中心动作称为独立演员" tabindex="-1">12.2 把 NAF 的中心动作称为独立演员 <a class="header-anchor" href="#_12-2-把-naf-的中心动作称为独立演员" aria-label="Permalink to &quot;12.2 把 NAF 的中心动作称为独立演员&quot;">​</a></h3><p>(\\mu(s)) 虽然直接输出动作，但它是受限 Q 函数的一部分，并通过 Q 回归共同学习，不等同于使用独立策略损失的 Actor-Critic。</p><h3 id="_12-3-把正定矩阵写成任意矩阵" tabindex="-1">12.3 把正定矩阵写成任意矩阵 <a class="header-anchor" href="#_12-3-把正定矩阵写成任意矩阵" aria-label="Permalink to &quot;12.3 把正定矩阵写成任意矩阵&quot;">​</a></h3><p>若 (P(s)) 不保证正定，中心动作不再必然是最大点，NAF 的解析性质就会失效。</p><h3 id="_12-4-把动作裁剪当成约束优化" tabindex="-1">12.4 把动作裁剪当成约束优化 <a class="header-anchor" href="#_12-4-把动作裁剪当成约束优化" aria-label="Permalink to &quot;12.4 把动作裁剪当成约束优化&quot;">​</a></h3><p>Clip（裁剪）只把数值压回边界，不能表达动作速率、组合约束和未来碰撞风险。</p><h3 id="_12-5-把方法复杂度只按网络数量计算" tabindex="-1">12.5 把方法复杂度只按网络数量计算 <a class="header-anchor" href="#_12-5-把方法复杂度只按网络数量计算" aria-label="Permalink to &quot;12.5 把方法复杂度只按网络数量计算&quot;">​</a></h3><p>候选数、动作优化迭代、矩阵构造、目标计算与控制频率都应计入真实成本。</p><h2 id="十三、学到什么程度才算掌握" tabindex="-1">十三、学到什么程度才算掌握 <a class="header-anchor" href="#十三、学到什么程度才算掌握" aria-label="Permalink to &quot;十三、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_13-1-能指出连续-dqn-的真正瓶颈" tabindex="-1">13.1 能指出连续 DQN 的真正瓶颈 <a class="header-anchor" href="#_13-1-能指出连续-dqn-的真正瓶颈" aria-label="Permalink to &quot;13.1 能指出连续 DQN 的真正瓶颈&quot;">​</a></h3><p>你应能解释为什么是动作最大化失效，而不是神经网络不能处理实数。</p><h3 id="_13-2-能推导-naf-的解析最大动作" tabindex="-1">13.2 能推导 NAF 的解析最大动作 <a class="header-anchor" href="#_13-2-能推导-naf-的解析最大动作" aria-label="Permalink to &quot;13.2 能推导 NAF 的解析最大动作&quot;">​</a></h3><p>你应能从负二次优势和正定矩阵推出 (a^*=\\mu(s))，并说明它依赖的结构假设。</p><h3 id="_13-3-能比较四条路线的代价" tabindex="-1">13.3 能比较四条路线的代价 <a class="header-anchor" href="#_13-3-能比较四条路线的代价" aria-label="Permalink to &quot;13.3 能比较四条路线的代价&quot;">​</a></h3><p>你应能从执行计算、动作维度、表达能力、探索和外推风险比较采样、梯度上升、NAF 与演员方法。</p><h3 id="_13-4-能守住自动驾驶应用边界" tabindex="-1">13.4 能守住自动驾驶应用边界 <a class="header-anchor" href="#_13-4-能守住自动驾驶应用边界" aria-label="Permalink to &quot;13.4 能守住自动驾驶应用边界&quot;">​</a></h3><p>连续动作可计算、统计回报更高和系统安全成立，是三种不同结论。</p><h3 id="_13-5-能进入稀疏奖励问题" tabindex="-1">13.5 能进入稀疏奖励问题 <a class="header-anchor" href="#_13-5-能进入稀疏奖励问题" aria-label="Permalink to &quot;13.5 能进入稀疏奖励问题&quot;">​</a></h3><p>即使动作求解已经解决，智能体若长期得不到有效奖励，评论家和演员仍没有学习方向。下一篇将进入奖励密度、奖励塑形和目标错配。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://raw.githubusercontent.com/datawhalechina/easy-rl/master/docs/chapter8/chapter8.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第八章针对连续动作的深度 Q 网络</a></p><p><a href="https://arxiv.org/abs/1603.00748" target="_blank" rel="noreferrer">Gu 等《Continuous Deep Q-Learning with Model-based Acceleration》</a></p><p><a href="https://arxiv.org/abs/1509.02971" target="_blank" rel="noreferrer">Lillicrap 等《Continuous Control with Deep Reinforcement Learning》</a></p><p><a href="https://spinningup.openai.com/en/latest/user/algorithms.html" target="_blank" rel="noreferrer">OpenAI Spinning Up 强化学习算法分类</a></p>',146)])])}const x=e(d,[["render",c]]);export{f as __pageData,x as default};
